import { useCallback, useEffect, useMemo, useState } from 'react';
import { Activity, AlertTriangle, ArrowDownToLine, ArrowUpRight, Beaker, Bell, Boxes, CalendarDays, Check, ChevronDown, ClipboardList, FlaskConical, Gauge, History, LayoutDashboard, LogOut, Menu, PackageCheck, Plus, Recycle, Search, ShieldCheck, Truck, UserRound, Users, X, LoaderCircle, Scale, FileText, Clock3, QrCode, RefreshCw } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import './index.css';

type UserProfile = { user_id: string; email: string; role: string; full_name: string };
type Row = Record<string, any>;
type Data = { dashboard: Row | null; requests: Row[]; wastes: Row[]; containers: Row[]; reagents: Row[]; operations: Row[]; alerts: Row[]; audit: Row[]; users: Row[] };
const emptyData: Data = { dashboard: null, requests: [], wastes: [], containers: [], reagents: [], operations: [], alerts: [], audit: [], users: [] };
const roles = ['Administrador', 'Gestor LGRP', 'Operacional', 'Laboratório', 'Consulta'];
const nav: { id: string; label: string; icon: LucideIcon; group: string }[] = [
  { id: 'dashboard', label: 'Visão geral', icon: LayoutDashboard, group: 'GESTÃO' },
  { id: 'requests', label: 'Solicitações', icon: ClipboardList, group: 'GESTÃO' },
  { id: 'wastes', label: 'Resíduos', icon: FlaskConical, group: 'GESTÃO' },
  { id: 'containers', label: 'Recipientes', icon: Boxes, group: 'ESTRUTURA' },
  { id: 'reagents', label: 'Reagentes', icon: Beaker, group: 'ESTRUTURA' },
  { id: 'operations', label: 'Operações', icon: Scale, group: 'RASTREAMENTO' },
  { id: 'alerts', label: 'Central de alertas', icon: Bell, group: 'RASTREAMENTO' },
  { id: 'reports', label: 'Relatórios', icon: FileText, group: 'INTELIGÊNCIA' },
  { id: 'audit', label: 'Auditoria', icon: History, group: 'ADMINISTRAÇÃO' },
  { id: 'users', label: 'Usuários e perfis', icon: Users, group: 'ADMINISTRAÇÃO' },
];
const permitted: Record<string, string[]> = { requests: ['Administrador', 'Gestor LGRP', 'Operacional', 'Laboratório'], wastes: ['Administrador', 'Gestor LGRP', 'Operacional', 'Laboratório'], containers: ['Administrador', 'Gestor LGRP', 'Operacional'], reagents: ['Administrador', 'Gestor LGRP', 'Operacional'], operations: ['Administrador', 'Gestor LGRP', 'Operacional'], alerts: ['Administrador', 'Gestor LGRP', 'Operacional'], users: ['Administrador'], audit: ['Administrador', 'Gestor LGRP'] };
const fmt = (value: any) => value ? new Date(value).toLocaleDateString('pt-BR') : '—';
const weight = (value: any, unit = 'kg') => `${Number(value || 0).toLocaleString('pt-BR', { maximumFractionDigits: 2 })} ${unit}`;

export default function App() {
  const [session, setSession] = useState<any>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [authLoading, setAuthLoading] = useState(true);
  const [authError, setAuthError] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [signUp, setSignUp] = useState(false);
  const [active, setActive] = useState('dashboard');
  const [data, setData] = useState<Data>(emptyData);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [modal, setModal] = useState('');
  const [selected, setSelected] = useState<Row | null>(null);
  const [busy, setBusy] = useState(false);
  const [toast, setToast] = useState('');
  const [mobileMenu, setMobileMenu] = useState(false);
  const [form, setForm] = useState<Row>({});
  const [reportPeriod, setReportPeriod] = useState('90');

  const loadProfile = useCallback(async (accessToken: string) => {
    const res = await fetch('/api/auth-profile', { headers: { Authorization: `Bearer ${accessToken}` } });
    if (!res.ok) throw new Error((await res.json()).error || 'Não foi possível carregar seu perfil.');
    setProfile(await res.json());
  }, []);
  useEffect(() => {
    const current = JSON.parse(localStorage.getItem('lgrp_session') || 'null');
    setSession(current);
    if (current) { loadProfile(current.access_token).catch((e: any) => { localStorage.removeItem('lgrp_session'); setSession(null); setAuthError(e.message); }); }
    setAuthLoading(false);
  }, [loadProfile]);
  useEffect(() => {
    if (!session) {
      setProfile(null);
      setData(emptyData);
    }
  }, [session]);

  const request = useCallback(async (path: string, init: RequestInit = {}) => {
    const token = session?.access_token;
    const res = await fetch(path, { ...init, headers: { 'Content-Type': 'application/json', ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(init.headers || {}) } });
    const body = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(body.error || 'Não foi possível concluir a operação.');
    return body;
  }, [session]);

  const refresh = useCallback(async (quiet = false) => {
    if (!session || !profile) return;
    if (!quiet) setLoading(true);
    setError('');
    try {
      const paths = ['/api/dashboard', '/api/requests', '/api/waste', '/api/assets?type=containers', '/api/assets?type=reagents', '/api/operations', '/api/alerts'];
      const results = await Promise.all(paths.map(path => request(path)));
      const next: Data = { ...emptyData, dashboard: results[0], requests: results[1], wastes: results[2], containers: results[3], reagents: results[4], operations: results[5], alerts: results[6] };
      if (['Administrador', 'Gestor LGRP'].includes(profile.role)) {
        try { next.audit = await request('/api/audit'); } catch { /* perfil restrito */ }
      }
      if (profile.role === 'Administrador') {
        try { next.users = await request('/api/auth-profile?all=true'); } catch { /* somente administração */ }
      }
      setData(next);
    } catch (e: any) { setError(e.message || 'Falha ao sincronizar os dados.'); }
    finally { setLoading(false); }
  }, [session, profile, request]);
  useEffect(() => { if (session && profile) refresh(); }, [session, profile, refresh]);

  useEffect(() => { if (!toast) return; const timer = setTimeout(() => setToast(''), 3600); return () => clearTimeout(timer); }, [toast]);
  const flash = (message: string) => { setToast(message); };
  const run = async (fn: () => Promise<any>, success: string) => {
    setBusy(true); setError('');
    try { await fn(); await refresh(true); setModal(''); setSelected(null); setForm({}); flash(success); }
    catch (e: any) { setError(e.message || 'Falha ao salvar.'); }
    finally { setBusy(false); }
  };
  const login = async (event: React.FormEvent) => {
    event.preventDefault(); setAuthError(''); setAuthLoading(true);
    try {
      const res = await fetch('/api/auth', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password, signUp }) });
      const result = await res.json();
      if (!res.ok) throw new Error(result.error || 'Não foi possível autenticar.');
      localStorage.setItem('lgrp_session', JSON.stringify(result.session));
      setSession(result.session);
      await loadProfile(result.session.access_token);
    } catch (e: any) { setAuthError(e.message || 'Não foi possível autenticar.'); }
    finally { setAuthLoading(false); }
  };
  const signOut = async () => { localStorage.removeItem('lgrp_session'); setSession(null); setProfile(null); setActive('dashboard'); };
  const change = (key: string, value: any) => setForm((current: Row) => ({ ...current, [key]: value }));
  const openModal = (name: string, row: Row | null = null) => { setSelected(row); setForm(row ? { ...row, ...(row.expiry_date ? { expiry_date: String(row.expiry_date).slice(0, 10) } : {}) } : {}); setModal(name); setError(''); };
  const canMutate = (module: string) => !permitted[module] || permitted[module].includes(profile?.role || '');
  const filtered = (rows: Row[]) => rows.filter(row => Object.values(row).some(value => String(value ?? '').toLowerCase().includes(search.toLowerCase())));
  const submit = async () => {
    if (modal === 'request') {
      if (!form.lab_name || !form.description || !form.quantity || !form.hazard_class) return setError('Preencha laboratório, descrição, quantidade e classe de risco.');
      return run(() => request('/api/requests', { method: 'POST', body: JSON.stringify(form) }), 'Solicitação registrada com sucesso.');
    }
    if (modal === 'waste') {
      if (!form.name || !form.lab_name || !form.quantity || !form.hazard_class) return setError('Preencha laboratório, resíduo, quantidade e classe de risco.');
      return run(() => request('/api/waste', { method: selected ? 'PUT' : 'POST', body: JSON.stringify({ ...form, id: selected?.id }) }), selected ? 'Resíduo atualizado.' : 'Resíduo cadastrado.');
    }
    if (modal === 'container' || modal === 'reagent') {
      if (!form.name && modal === 'reagent') return setError('Informe o nome do reagente.');
      if (!form.type && modal === 'container') return setError('Informe o tipo de recipiente.');
      return run(() => request('/api/assets', { method: selected ? 'PUT' : 'POST', body: JSON.stringify({ ...form, asset_type: modal === 'container' ? 'containers' : 'reagents', id: selected?.id }) }), 'Cadastro atualizado.');
    }
    if (modal === 'schedule') return run(() => request('/api/requests', { method: 'PUT', body: JSON.stringify({ id: selected?.id, status: 'Agendada', scheduled_at: form.scheduled_at, container_code: form.container_code }) }), 'Coleta agendada.');
    if (modal === 'operation') {
      if (!form.waste_id || !form.action) return setError('Selecione o resíduo e o tipo de operação.');
      if (form.action === 'Coleta' && !form.net_weight) return setError('Informe a pesagem líquida da coleta.');
      return run(() => request('/api/operations', { method: 'POST', body: JSON.stringify(form) }), 'Operação registrada e rastreabilidade atualizada.');
    }
    if (modal === 'role') return run(() => request('/api/auth-profile', { method: 'PUT', body: JSON.stringify({ user_id: selected?.user_id, role: form.role }) }), 'Perfil de acesso atualizado.');
  };
  const approveRequest = (row: Row) => run(() => request('/api/requests', { method: 'PUT', body: JSON.stringify({ id: row.id, status: 'Aprovada' }) }), 'Solicitação aprovada.');
  const resolveAlert = (row: Row) => run(() => request('/api/alerts', { method: 'PUT', body: JSON.stringify({ id: row.id, resolved: !row.resolved }) }), row.resolved ? 'Alerta reaberto.' : 'Alerta resolvido.');

  const stat = data.dashboard || {};
  const visibleNav = nav.filter(item => !['audit', 'users'].includes(item.id) || canMutate(item.id));
  const pageTitle = nav.find(item => item.id === active)?.label || 'Visão geral';

  if (authLoading) return <div className="auth-loading"><LoaderCircle className="spin" size={26} /> Verificando acesso institucional…</div>;
  if (!session || !profile) return <main className="login-shell"><section className="login-brand"><div className="brand-lockup"><div className="brand-mark"><Recycle size={25} /></div><div><b>LGRP</b><span>UFLA · Gestão de resíduos</span></div></div><div className="login-message"><span className="eyebrow">PLATAFORMA INSTITUCIONAL</span><h1>Segurança em cada etapa. <em>Responsabilidade em todo ciclo.</em></h1><p>Gestão integrada de resíduos químicos perigosos — da solicitação à destinação final.</p><div className="login-trust"><ShieldCheck size={17} /> Acesso protegido · Operações auditáveis</div></div><div className="login-foot">Universidade Federal de Lavras <span>•</span> Laboratório de Gestão de Resíduos Perigosos</div></section><section className="login-panel"><form className="login-card" onSubmit={login}><div className="mobile-brand"><div className="brand-mark"><Recycle size={22} /></div><b>LGRP · UFLA</b></div><span className="eyebrow">AMBIENTE SEGURO</span><h2>{signUp ? 'Crie seu acesso' : 'Bem-vindo de volta'}</h2><p className="muted">{signUp ? 'Seu novo perfil será criado com acesso de Consulta.' : 'Entre com suas credenciais institucionais.'}</p><label>E-mail institucional<input type="email" autoComplete="email" required value={email} onChange={e => setEmail(e.target.value)} placeholder="nome@ufla.br" /></label><label>Senha<input type="password" autoComplete={signUp ? 'new-password' : 'current-password'} minLength={6} required value={password} onChange={e => setPassword(e.target.value)} placeholder="Mínimo de 6 caracteres" /></label>{authError && <div className="inline-error"><AlertTriangle size={15} />{authError}</div>}<button className="btn-primary full" type="submit" disabled={authLoading}>{authLoading ? <LoaderCircle className="spin" size={17} /> : null}{signUp ? 'Criar conta' : 'Entrar no sistema'} <ArrowUpRight size={16} /></button><button className="text-button full" type="button" onClick={() => { setSignUp(!signUp); setAuthError(''); }}>{signUp ? 'Já tenho acesso — entrar' : 'Solicitar novo acesso'}</button></form><p className="login-legal">Uso restrito a usuários autorizados. Ações críticas são registradas para fins de segurança e conformidade.</p></section></main>;

  return <div className="app-shell"><aside className={`sidebar ${mobileMenu ? 'open' : ''}`}><div className="brand-lockup sidebar-brand"><div className="brand-mark"><Recycle size={24} /></div><div><b>LGRP</b><span>UFLA · Resíduos perigosos</span></div><button className="icon-button close-mobile" onClick={() => setMobileMenu(false)} aria-label="Fechar menu"><X size={18} /></button></div><div className="institution-tag"><span className="status-dot" /> AMBIENTE INSTITUCIONAL</div><nav aria-label="Navegação principal">{['GESTÃO', 'ESTRUTURA', 'RASTREAMENTO', 'INTELIGÊNCIA', 'ADMINISTRAÇÃO'].map(group => <div className="nav-group" key={group}><span className="nav-caption">{group}</span>{visibleNav.filter(item => item.group === group).map(item => { const Icon = item.icon; return <button key={item.id} className={`nav-item ${active === item.id ? 'selected' : ''}`} onClick={() => { setActive(item.id); setMobileMenu(false); setSearch(''); }}><Icon size={17} strokeWidth={1.8} /><span>{item.label}</span>{item.id === 'alerts' && data.alerts.filter(a => !a.resolved).length > 0 && <b className="nav-count">{data.alerts.filter(a => !a.resolved).length}</b>}</button>; })}</div>)}</nav><div className="sidebar-bottom"><div className="support-card"><div className="support-icon"><ShieldCheck size={17} /></div><b>Rastreabilidade ativa</b><span>Operações críticas registradas em trilha de auditoria.</span></div><button className="profile-mini" onClick={signOut}><div className="avatar">{(profile.full_name || profile.email).slice(0, 1).toUpperCase()}</div><span><b>{profile.full_name || profile.email.split('@')[0]}</b><small>{profile.role}</small></span><LogOut size={16} /></button></div></aside>
  <main className="main-area"><header className="topbar"><button className="icon-button menu-toggle" onClick={() => setMobileMenu(true)} aria-label="Abrir menu"><Menu size={20} /></button><div className="breadcrumbs"><span>UFLA</span><span className="crumb-slash">/</span><b>{pageTitle}</b></div><div className="top-actions"><div className="sync-indicator"><span className="status-dot" /> Sistema operacional</div><button className="icon-button top-alert" onClick={() => setActive('alerts')} aria-label="Abrir alertas"><Bell size={18} />{data.alerts.some(a => !a.resolved) && <i />}</button><div className="top-user"><div className="avatar">{(profile.full_name || profile.email).slice(0, 1).toUpperCase()}</div><span>{profile.full_name || profile.email.split('@')[0]}</span><ChevronDown size={14} /></div></div></header>
  <div className="page-wrap"><div className="page-heading"><div><div className="eyebrow">LABORATÓRIO DE GESTÃO DE RESÍDUOS PERIGOSOS</div><h1>{active === 'dashboard' ? 'Painel institucional' : pageTitle}</h1><p>{active === 'dashboard' ? 'Acompanhamento integrado do ciclo de resíduos químicos da universidade.' : `${pageTitle} · gestão operacional e rastreabilidade do ciclo de resíduos.`}</p></div><div className="heading-actions"><button className="btn-secondary" onClick={() => refresh()} disabled={loading}><RefreshCw size={15} className={loading ? 'spin' : ''} /> Atualizar</button>{active === 'dashboard' && canMutate('requests') && <button className="btn-primary" onClick={() => openModal('request')}><Plus size={17} /> Nova solicitação</button>}{active === 'requests' && canMutate('requests') && <button className="btn-primary" onClick={() => openModal('request')}><Plus size={17} /> Nova solicitação</button>}{active === 'wastes' && canMutate('wastes') && <button className="btn-primary" onClick={() => openModal('waste')}><Plus size={17} /> Cadastrar resíduo</button>}{active === 'containers' && canMutate('containers') && <button className="btn-primary" onClick={() => openModal('container')}><Plus size={17} /> Novo recipiente</button>}{active === 'reagents' && canMutate('reagents') && <button className="btn-primary" onClick={() => openModal('reagent')}><Plus size={17} /> Novo reagente</button>}{active === 'operations' && canMutate('operations') && <button className="btn-primary" onClick={() => openModal('operation')}><Plus size={17} /> Registrar operação</button>}</div></div>
  {error && <div className="error-banner" role="alert"><AlertTriangle size={16} />{error}<button onClick={() => setError('')} aria-label="Fechar"><X size={15} /></button></div>}
  {loading && !data.dashboard ? <div className="loading-card"><LoaderCircle className="spin" size={22} /> Carregando dados institucionais…</div> : <>
    {active === 'dashboard' && <Dashboard data={data} canMutate={canMutate} openModal={openModal} setActive={setActive} />}
    {active === 'requests' && <Requests rows={filtered(data.requests)} allRows={data.requests} profile={profile} openModal={openModal} approveRequest={approveRequest} canMutate={canMutate} search={search} setSearch={setSearch} />}
    {active === 'wastes' && <Wastes rows={filtered(data.wastes)} openModal={openModal} canMutate={canMutate} search={search} setSearch={setSearch} />}
    {active === 'containers' && <Assets type="containers" rows={filtered(data.containers)} openModal={openModal} canMutate={canMutate} search={search} setSearch={setSearch} />}
    {active === 'reagents' && <Assets type="reagents" rows={filtered(data.reagents)} openModal={openModal} canMutate={canMutate} search={search} setSearch={setSearch} />}
    {active === 'operations' && <Operations rows={filtered(data.operations)} wastes={data.wastes} openModal={openModal} canMutate={canMutate} search={search} setSearch={setSearch} />}
    {active === 'alerts' && <Alerts rows={filtered(data.alerts)} resolveAlert={resolveAlert} canMutate={canMutate} search={search} setSearch={setSearch} />}
    {active === 'reports' && <Reports data={data} period={reportPeriod} setPeriod={setReportPeriod} />}
    {active === 'audit' && <Audit rows={filtered(data.audit)} search={search} setSearch={setSearch} />}
    {active === 'users' && <UsersPanel rows={data.users} openModal={openModal} />}
  </>}
  <footer className="page-footer"><span>© Universidade Federal de Lavras · LGRP</span><span>Gestão responsável · Conformidade · Rastreabilidade</span></footer></div></main>
  {mobileMenu && <button className="mobile-scrim" onClick={() => setMobileMenu(false)} aria-label="Fechar menu" />}
  {modal && <Modal title={modalTitle(modal, selected)} close={() => { setModal(''); setError(''); }}><ModalFields modal={modal} form={form} change={change} wastes={data.wastes} containers={data.containers} selected={selected} users={data.users} />{error && <div className="inline-error"><AlertTriangle size={15} />{error}</div>}<div className="modal-actions">{modal === 'qr' ? <button className="btn-primary" onClick={() => setModal('')}>Concluir</button> : <><button className="btn-secondary" onClick={() => { setModal(''); setError(''); }}>Cancelar</button><button className="btn-primary" disabled={busy} onClick={submit}>{busy ? <LoaderCircle className="spin" size={16} /> : <Check size={16} />}{busy ? 'Salvando…' : 'Confirmar registro'}</button></>}</div></Modal>}
  {toast && <div className="toast" role="status"><Check size={17} />{toast}</div>}
  </div>;
}

function Modal({ title, close, children }: { title: string; close: () => void; children: React.ReactNode }) {
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => { if (event.key === 'Escape') close(); };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [close]);
  return <div className="modal-backdrop" onMouseDown={event => { if (event.target === event.currentTarget) close(); }}><section className="modal-card" role="dialog" aria-modal="true" aria-label={title}><header className="modal-head"><h2>{title}</h2><button className="icon-button" onClick={close} aria-label="Fechar janela"><X size={18} /></button></header><div className="modal-body">{children}</div></section></div>;
}

function Dashboard({ data, canMutate, openModal, setActive }: { data: Data; canMutate: (s: string) => boolean; openModal: (s: string, r?: Row | null) => void; setActive: (s: string) => void }) {
  const stats = data.dashboard || {};
  const stages = stats.stages || [];
  const weekly = stats.monthly || [];
  const maxMonthly = Math.max(1, ...weekly.map((x: Row) => Number(x.total || 0)));
  const pending = data.requests.filter(r => ['Recebida', 'Em análise'].includes(r.status));
  return <><div className="stats-grid"><StatCard label="Resíduos em ciclo" value={stats.active_wastes || 0} unit="registros" icon={FlaskConical} tone="green" delta="Rastreabilidade por código" /><StatCard label="Massa em armazenamento" value={weight(stats.stored_weight, 'kg')} icon={Boxes} tone="blue" delta="Estoque atual no LGRP" /><StatCard label="Solicitações pendentes" value={stats.pending_requests || 0} icon={Clock3} tone="amber" delta="Aguardando análise" /><StatCard label="Alertas ativos" value={stats.active_alerts || 0} icon={AlertTriangle} tone="red" delta="Validade e operação" /></div>
  <div className="dashboard-grid"><section className="panel trend-panel"><div className="panel-head"><div><span className="eyebrow">FLUXO DE MASSA</span><h2>Geração mensal registrada</h2></div><span className="period-chip"><Activity size={14} /> Últimos 6 meses</span></div><div className="chart-legend"><span><i className="legend-dot green-dot" /> Massa registrada (kg)</span><span className="chart-total">{weight(stats.period_weight, 'kg')} <small>no período</small></span></div><div className="bar-chart" aria-label="Gráfico de massa registrada nos últimos seis meses">{weekly.map((item: Row) => <div className="bar-column" key={item.label}><span className="bar-value">{Number(item.total || 0).toLocaleString('pt-BR')}</span><div className="bar-track"><div className="bar" style={{ height: `${Math.max(6, Number(item.total || 0) / maxMonthly * 100)}%` }} /></div><span className="bar-label">{item.label}</span></div>)}</div><div className="chart-foot"><span>Dados de pesagens e geração registrados</span><button className="link-button" onClick={() => setActive('reports')}>Ver relatórios <ArrowUpRight size={14} /></button></div></section>
  <section className="panel stage-panel"><div className="panel-head"><div><span className="eyebrow">CICLO DE VIDA</span><h2>Resíduos por etapa</h2></div><button className="icon-button" onClick={() => setActive('wastes')} aria-label="Ver resíduos"><ArrowUpRight size={17} /></button></div><div className="stage-list">{stages.map((item: Row, i: number) => { const total = Math.max(1, stats.active_wastes || 1); return <div className="stage-row" key={item.status}><div className={`stage-icon stage-${i}`}><span /></div><div className="stage-info"><div><b>{item.status}</b><span>{item.count}</span></div><div className="progress-track"><span style={{ width: `${Math.min(100, Number(item.count) / total * 100)}%` }} /></div></div></div>; })}{stages.length === 0 && <Empty text="Nenhum resíduo cadastrado." />}</div><button className="stage-link" onClick={() => setActive('wastes')}>Acessar rastreabilidade completa <ArrowUpRight size={14} /></button></section></div>
  <div className="lower-grid"><section className="panel requests-panel"><div className="panel-head"><div><span className="eyebrow">FILA DE ATENDIMENTO</span><h2>Solicitações recentes</h2></div><button className="link-button" onClick={() => setActive('requests')}>Ver todas <ArrowUpRight size={14} /></button></div><div className="compact-list">{data.requests.slice(0, 4).map(row => <div className="compact-row" key={row.id}><div className="lab-avatar">{(row.lab_name || 'L').slice(0, 2).toUpperCase()}</div><div className="compact-main"><b>{row.lab_name}</b><span>{row.description} · {row.code}</span></div><Status status={row.status} /><span className="compact-date">{fmt(row.requested_at)}</span></div>)}{!data.requests.length && <Empty text="Nenhuma solicitação registrada." />}</div></section>
  <section className="panel alert-panel"><div className="panel-head"><div><span className="eyebrow">ATENÇÃO OPERACIONAL</span><h2>Alertas prioritários</h2></div><button className="link-button" onClick={() => setActive('alerts')}>Central <ArrowUpRight size={14} /></button></div>{data.alerts.filter(a => !a.resolved).slice(0, 3).map(row => <div className="alert-brief" key={row.id}><div className={`alert-brief-icon ${row.severity}`}><AlertTriangle size={16} /></div><div><b>{row.title}</b><span>{row.message}</span><small>{row.related_code} · {fmt(row.created_at)}</small></div></div>)}{!data.alerts.some(a => !a.resolved) && <div className="all-clear"><ShieldCheck size={22} /><span>Nenhum alerta ativo</span><small>Operação sem pendências críticas</small></div>}</section></div>
  <div className="quick-actions"><div><span className="eyebrow">ACESSO RÁPIDO</span><h2>O que você precisa fazer?</h2></div><div className="quick-buttons">{canMutate('requests') && <button onClick={() => openModal('request')}><span className="quick-icon q-green"><ClipboardList size={18} /></span><span><b>Nova solicitação</b><small>Iniciar atendimento</small></span><ArrowUpRight size={15} /></button>}{canMutate('wastes') && <button onClick={() => { setActive('wastes'); openModal('waste'); }}><span className="quick-icon q-blue"><QrCode size={18} /></span><span><b>Cadastrar resíduo</b><small>Identificar e rastrear</small></span><ArrowUpRight size={15} /></button>}{canMutate('operations') && <button onClick={() => { setActive('operations'); openModal('operation'); }}><span className="quick-icon q-amber"><Scale size={18} /></span><span><b>Registrar pesagem</b><small>Coleta ou tratamento</small></span><ArrowUpRight size={15} /></button>}</div></div>
  </>;
}
function StatCard({ label, value, unit, icon: Icon, tone, delta }: { label: string; value: any; unit?: string; icon: LucideIcon; tone: string; delta: string }) { return <div className="stat-card"><div className="stat-top"><span>{label}</span><div className={`stat-icon ${tone}`}><Icon size={18} /></div></div><div className="stat-value">{value} {unit && <small>{unit}</small>}</div><div className="stat-delta"><span className={`delta-mark ${tone}`}><ArrowUpRight size={12} /></span>{delta}</div></div>; }
function TableToolbar({ search, setSearch, placeholder }: { search: string; setSearch: (s: string) => void; placeholder: string }) { return <div className="table-toolbar"><label className="search-box"><Search size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder={placeholder} /></label><span className="table-count"><span className="status-dot" /> Dados sincronizados</span></div>; }
function Requests({ rows, allRows, profile, openModal, approveRequest, canMutate, search, setSearch }: any) { return <><div className="metric-strip"><div><span>Solicitações totais</span><b>{allRows.length}</b></div><div><span>Em análise</span><b>{allRows.filter((r: Row) => ['Recebida', 'Em análise'].includes(r.status)).length}</b></div><div><span>Agendadas</span><b>{allRows.filter((r: Row) => r.status === 'Agendada').length}</b></div><div><span>Atendidas</span><b>{allRows.filter((r: Row) => r.status === 'Coletada').length}</b></div></div><section className="panel table-panel"><TableToolbar search={search} setSearch={setSearch} placeholder="Buscar por código, laboratório ou resíduo…" /><div className="table-scroll"><table><thead><tr><th>CÓDIGO / DATA</th><th>LABORATÓRIO GERADOR</th><th>RESÍDUO / CLASSE</th><th>QUANTIDADE</th><th>STATUS</th><th>AÇÕES</th></tr></thead><tbody>{rows.map((row: Row) => <tr key={row.id}><td><b className="mono">{row.code}</b><small>{fmt(row.requested_at)}</small></td><td><b>{row.lab_name}</b><small>{row.requester || 'Solicitante'}</small></td><td>{row.description}<small>{row.hazard_class}</small></td><td>{weight(row.quantity, row.unit)}</td><td><Status status={row.status} /></td><td><div className="row-actions">{row.status === 'Recebida' && canMutate('requests') && ['Administrador', 'Gestor LGRP'].includes(profile.role) && <button className="tiny-button" onClick={() => approveRequest(row)}>Aprovar</button>}{['Aprovada', 'Em análise'].includes(row.status) && canMutate('requests') && <button className="tiny-button" onClick={() => openModal('schedule', row)}>Agendar</button>}{row.status === 'Agendada' && canMutate('operations') && <button className="tiny-button" onClick={() => openModal('operation', { action: 'Coleta', waste_id: row.waste_id || '', operator: profile.full_name || profile.email, request_id: row.id })}>Coletar</button>}<button className="icon-button small" title="Identificação QR" onClick={() => openModal('qr', row)}><QrCode size={15} /></button></div></td></tr>)}</tbody></table>{!rows.length && <Empty text="Nenhuma solicitação corresponde à busca." />}</div></section></>; }
function Wastes({ rows, openModal, canMutate, search, setSearch }: any) { return <><div className="info-banner"><QrCode size={18} /><div><b>Identificação e rastreabilidade individual</b><span>Cada resíduo recebe código único e QR para consulta rápida de origem, etapa e histórico operacional.</span></div></div><section className="panel table-panel"><TableToolbar search={search} setSearch={setSearch} placeholder="Código, laboratório, classe ou localização…" /><div className="table-scroll"><table><thead><tr><th>CÓDIGO / QR</th><th>RESÍDUO / COMPOSIÇÃO</th><th>LABORATÓRIO</th><th>CLASSE / ESTADO</th><th>MASSA / VOLUME</th><th>ETAPA / LOCAL</th><th>AÇÕES</th></tr></thead><tbody>{rows.map((row: Row) => <tr key={row.id}><td><button className="code-link" onClick={() => openModal('qr', row)}><QrCode size={15} />{row.code}</button><small>Gerado {fmt(row.generated_at)}</small></td><td><b>{row.name}</b><small>{row.composition || 'Composição não informada'}</small></td><td>{row.lab_name}</td><td><span className="hazard-tag">{row.hazard_class}</span><small>{row.physical_state}</small></td><td><b>{weight(row.quantity, row.unit)}</b></td><td><Status status={row.status} /><small>{row.storage_location || '—'}</small></td><td><div className="row-actions"><button className="icon-button small" title="Ver QR Code" onClick={() => openModal('qr', row)}><QrCode size={15} /></button>{canMutate('wastes') && <button className="icon-button small" title="Editar cadastro" onClick={() => openModal('waste', row)}><FileText size={15} /></button>}</div></td></tr>)}</tbody></table>{!rows.length && <Empty text="Nenhum resíduo encontrado." />}</div></section></>; }
function Assets({ type, rows, openModal, canMutate, search, setSearch }: any) { const containers = type === 'containers'; const expired = rows.filter((r: Row) => r.expiry_date && new Date(r.expiry_date) < new Date()).length; return <><div className="metric-strip"><div><span>Itens cadastrados</span><b>{rows.length}</b></div><div><span>{containers ? 'Disponíveis' : 'Vencem em 90 dias'}</span><b>{containers ? rows.filter((r: Row) => r.status === 'Disponível').length : rows.filter((r: Row) => r.expiry_date && new Date(r.expiry_date) > new Date() && new Date(r.expiry_date) < new Date(Date.now() + 90 * 86400000)).length}</b></div><div><span>{containers ? 'Em uso' : 'Vencidos'}</span><b>{containers ? rows.filter((r: Row) => r.status === 'Em uso').length : expired}</b></div><div><span>{containers ? 'Inspeção pendente' : 'Unidades registradas'}</span><b>{containers ? rows.filter((r: Row) => r.status === 'Inspeção').length : rows.length}</b></div></div><section className="panel table-panel"><TableToolbar search={search} setSearch={setSearch} placeholder="Buscar por código, descrição ou local…" /><div className="table-scroll"><table><thead><tr>{containers ? <><th>CÓDIGO / QR</th><th>RECIPIENTE</th><th>CAPACIDADE</th><th>LOCAL / LABORATÓRIO</th><th>VALIDADE</th><th>STATUS</th><th>AÇÕES</th></> : <><th>CÓDIGO / QR</th><th>REAGENTE</th><th>LABORATÓRIO</th><th>ESTOQUE</th><th>VALIDADE</th><th>STATUS</th><th>AÇÕES</th></>}</tr></thead><tbody>{rows.map((row: Row) => { const isExpired = row.expiry_date && new Date(row.expiry_date) < new Date(); const soon = row.expiry_date && !isExpired && new Date(row.expiry_date) < new Date(Date.now() + 90 * 86400000); return <tr key={row.id}><td><button className="code-link" onClick={() => openModal('qr', row)}><QrCode size={15} />{row.code}</button></td><td><b>{containers ? row.type : row.name}</b><small>{containers ? row.material || 'Material não informado' : row.cas_number || 'CAS não informado'}</small></td><td>{containers ? weight(row.capacity, row.unit) : row.lab_name}</td><td>{containers ? row.location || row.assigned_lab || '—' : weight(row.quantity, row.unit)}</td><td className={isExpired || soon ? 'expiry-warning' : ''}>{fmt(row.expiry_date)}{(isExpired || soon) && <small>{isExpired ? 'Vencido' : 'Vence em breve'}</small>}</td><td><Status status={isExpired ? 'Vencido' : row.status} /></td><td><button className="icon-button small" onClick={() => openModal('qr', row)} title="Ver QR Code"><QrCode size={15} /></button>{canMutate(type) && <button className="icon-button small" onClick={() => openModal(containers ? 'container' : 'reagent', row)} title="Editar"><FileText size={15} /></button>}</td></tr>; })}</tbody></table>{!rows.length && <Empty text={containers ? 'Nenhum recipiente cadastrado.' : 'Nenhum reagente cadastrado.'} />}</div></section></>; }
function Operations({ rows, wastes, openModal, canMutate, search, setSearch }: any) { return <><div className="metric-strip"><div><span>Operações registradas</span><b>{rows.length}</b></div><div><span>Coletas</span><b>{rows.filter((r: Row) => r.action === 'Coleta').length}</b></div><div><span>Tratamentos</span><b>{rows.filter((r: Row) => r.action === 'Tratamento').length}</b></div><div><span>Destinações</span><b>{rows.filter((r: Row) => r.action === 'Destinação').length}</b></div></div><div className="info-banner blue"><Scale size={18} /><div><b>Cadeia de custódia</b><span>Registre pesagem bruta, tara, massa líquida, responsável técnico e evidências de tratamento/destinação.</span></div></div><section className="panel table-panel"><TableToolbar search={search} setSearch={setSearch} placeholder="Buscar operação, responsável ou código…" /><div className="table-scroll"><table><thead><tr><th>DATA / OPERAÇÃO</th><th>RESÍDUO</th><th>RESPONSÁVEL</th><th>PESAGEM LÍQUIDA</th><th>MÉTODO / DESTINO</th><th>REGISTRO</th></tr></thead><tbody>{rows.map((row: Row) => <tr key={row.id}><td><b>{row.action}</b><small>{fmt(row.occurred_at)}</small></td><td><b className="mono">{row.waste_code || row.waste_id}</b><small>{row.waste_name || 'Resíduo vinculado'}</small></td><td>{row.operator}</td><td>{row.net_weight ? weight(row.net_weight) : '—'}<small>{row.gross_weight ? `Bruta ${weight(row.gross_weight)} · tara ${weight(row.tare_weight)}` : ''}</small></td><td>{row.method || row.destination || '—'}<small>{row.manifest ? `Manifesto ${row.manifest}` : row.outcome || ''}</small></td><td><span className="mono subtle">OP-{String(row.id).padStart(5, '0')}</span></td></tr>)}</tbody></table>{!rows.length && <Empty text="Nenhuma operação registrada." />}</div></section></>; }
function Alerts({ rows, resolveAlert, canMutate, search, setSearch }: any) { const active = rows.filter((r: Row) => !r.resolved); return <><div className="metric-strip"><div><span>Alertas ativos</span><b className="red-number">{active.length}</b></div><div><span>Críticos</span><b>{active.filter((r: Row) => r.severity === 'critical').length}</b></div><div><span>Validade de reagente</span><b>{active.filter((r: Row) => r.type === 'validade').length}</b></div><div><span>Resolvidos</span><b>{rows.filter((r: Row) => r.resolved).length}</b></div></div><section className="panel table-panel"><TableToolbar search={search} setSearch={setSearch} placeholder="Buscar alerta, código ou categoria…" /><div className="alert-list">{rows.map((row: Row) => <div className={`alert-row ${row.resolved ? 'resolved' : ''}`} key={row.id}><div className={`alert-brief-icon ${row.severity}`}><AlertTriangle size={17} /></div><div className="alert-row-main"><div><span className={`severity-label ${row.severity}`}>{row.severity === 'critical' ? 'CRÍTICO' : row.severity === 'warning' ? 'ATENÇÃO' : 'INFORMATIVO'}</span><span className="alert-category">{row.type}</span><span className="alert-date">{fmt(row.created_at)}</span></div><b>{row.title}</b><p>{row.message}</p><small>Identificação vinculada: {row.related_code || '—'}</small></div><div>{canMutate('alerts') && <button className={`tiny-button ${row.resolved ? '' : 'success'}`} onClick={() => resolveAlert(row)}>{row.resolved ? 'Reabrir' : 'Resolver'}</button>}</div></div>)}{!rows.length && <Empty text="Nenhum alerta encontrado." />}</div></section></>; }
function Reports({ data, period, setPeriod }: any) { const [message, setMessage] = useState(''); const records = data.operations.filter((r: Row) => !r.occurred_at || new Date(r.occurred_at) >= new Date(Date.now() - Number(period) * 86400000)); const gross = records.reduce((sum: number, r: Row) => sum + Number(r.net_weight || 0), 0); const exportCsv = () => { const rows = [['Data', 'Operação', 'Código resíduo', 'Responsável', 'Massa líquida (kg)', 'Método', 'Manifesto'], ...records.map((r: Row) => [fmt(r.occurred_at), r.action, r.waste_code || r.waste_id, r.operator, r.net_weight || '', r.method || '', r.manifest || ''])]; const csv = '\ufeff' + rows.map((r: any[]) => r.map(x => `"${String(x ?? '').replaceAll('"', '""')}"`).join(';')).join('\n'); const link = document.createElement('a'); link.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); link.download = 'lgrp-relatorio-operacional.csv'; link.click(); URL.revokeObjectURL(link.href); setMessage('Relatório CSV exportado com os dados registrados.'); }; return <><div className="report-toolbar"><div><b>Relatório operacional</b><span>Indicadores consolidados a partir dos registros do sistema.</span></div><div><select value={period} onChange={e => setPeriod(e.target.value)} aria-label="Período"><option value="30">Últimos 30 dias</option><option value="90">Últimos 90 dias</option><option value="365">Últimos 12 meses</option><option value="3650">Todo o período</option></select><button className="btn-primary" onClick={exportCsv}><ArrowDownToLine size={16} /> Exportar CSV</button></div></div>{message && <div className="success-banner"><Check size={15} />{message}<button onClick={() => setMessage('')} aria-label="Fechar"><X size={15} /></button></div>}<div className="report-cards"><StatCard label="Massa movimentada" value={weight(gross)} icon={Scale} tone="green" delta="Operações no período" /><StatCard label="Resíduos cadastrados" value={data.wastes.length} icon={FlaskConical} tone="blue" delta="Ciclo de rastreabilidade" /><StatCard label="Solicitações atendidas" value={data.requests.filter((r: Row) => r.status === 'Coletada').length} icon={PackageCheck} tone="amber" delta="Coletas confirmadas" /><StatCard label="Destinações registradas" value={data.operations.filter((r: Row) => r.action === 'Destinação').length} icon={Truck} tone="red" delta="Manifestos e saídas" /></div><section className="panel report-table"><div className="panel-head"><div><span className="eyebrow">DADOS AUDITÁVEIS</span><h2>Movimentações no período</h2></div><span className="period-chip">{records.length} registros</span></div><div className="table-scroll"><table><thead><tr><th>DATA</th><th>TIPO</th><th>CÓDIGO DE RASTREIO</th><th>RESPONSÁVEL</th><th>MASSA (KG)</th><th>MÉTODO / DESTINO</th></tr></thead><tbody>{records.slice(0, 40).map((r: Row) => <tr key={r.id}><td>{fmt(r.occurred_at)}</td><td>{r.action}</td><td className="mono">{r.waste_code || r.waste_id}</td><td>{r.operator}</td><td>{r.net_weight ? weight(r.net_weight) : '—'}</td><td>{r.method || r.destination || '—'}</td></tr>)}</tbody></table>{!records.length && <Empty text="Não há operações no período selecionado." />}</div></section></>; }
function Audit({ rows, search, setSearch }: any) { return <><div className="info-banner"><ShieldCheck size={18} /><div><b>Trilha de auditoria imutável por operação</b><span>Registros de autoria, perfil, evento e detalhes permitem reconstruir ações críticas para conformidade e investigação.</span></div></div><section className="panel table-panel"><TableToolbar search={search} setSearch={setSearch} placeholder="Buscar ação, entidade ou responsável…" /><div className="table-scroll"><table><thead><tr><th>DATA E HORA</th><th>ATOR / PERFIL</th><th>EVENTO</th><th>ENTIDADE</th><th>DETALHES</th><th>REFERÊNCIA</th></tr></thead><tbody>{rows.map((row: Row) => <tr key={row.id}><td><b>{new Date(row.created_at).toLocaleString('pt-BR')}</b></td><td>{row.actor}<small>{row.role}</small></td><td><span className="audit-action">{row.action}</span></td><td>{row.entity}</td><td className="detail-cell">{JSON.stringify(row.details || {})}</td><td className="mono">{row.entity_id || '—'}</td></tr>)}</tbody></table>{!rows.length && <Empty text="Nenhuma operação auditável registrada." />}</div></section></>; }
function UsersPanel({ rows, openModal }: any) { return <><div className="info-banner"><Users size={18} /><div><b>Perfis institucionais com privilégio mínimo</b><span>Novas contas iniciam com Consulta. Somente Administradores podem atribuir permissões operacionais.</span></div></div><section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>USUÁRIO</th><th>E-MAIL</th><th>PERFIL</th><th>CONTROLE DE ACESSO</th></tr></thead><tbody>{rows.map((row: Row) => <tr key={row.user_id}><td><div className="user-name"><div className="avatar">{(row.full_name || row.email).slice(0, 1).toUpperCase()}</div><b>{row.full_name || 'Usuário institucional'}</b></div></td><td>{row.email}</td><td><span className="role-chip">{row.role}</span></td><td><button className="tiny-button" onClick={() => openModal('role', row)}>Alterar perfil</button></td></tr>)}</tbody></table>{!rows.length && <Empty text="Não há perfis de usuário disponíveis." />}</div></section></>; }
function Status({ status }: { status: string }) { const normalized = (status || '').toLowerCase(); const tone = ['coletada', 'disponível', 'tratado', 'destinado', 'aprovada', 'recuperado'].some(s => normalized.includes(s)) ? 'green' : ['vencido', 'crítico', 'reprovado'].some(s => normalized.includes(s)) ? 'red' : ['agendada', 'em tratamento', 'em armazenamento', 'em uso', 'em análise'].some(s => normalized.includes(s)) ? 'blue' : 'amber'; return <span className={`status-pill ${tone}`}><i />{status || 'Pendente'}</span>; }
function Empty({ text }: { text: string }) { return <div className="empty-state"><div><Search size={19} /></div><b>{text}</b><span>Os registros aparecerão aqui após sincronização.</span></div>; }
function modalTitle(modal: string, selected: Row | null) { const titles: Row = { request: 'Nova solicitação de coleta', waste: selected ? 'Editar cadastro de resíduo' : 'Cadastrar novo resíduo', container: selected ? 'Editar recipiente' : 'Cadastrar recipiente', reagent: selected ? 'Editar reagente' : 'Cadastrar reagente', schedule: 'Agendar coleta', operation: 'Registrar operação e pesagem', role: 'Alterar perfil de acesso', qr: 'Identificação rastreável' }; return titles[modal] || 'Registro'; }
function ModalFields({ modal, form, change, wastes, containers, selected, users }: any) {
  const input = (label: string, key: string, type = 'text', options?: string[], placeholder?: string) => <label>{label}{options ? <select value={form[key] || ''} onChange={e => change(key, e.target.value)}><option value="">Selecione…</option>{options.map((option: string) => <option key={option}>{option}</option>)}</select> : <input type={type} value={form[key] ?? ''} placeholder={placeholder || ''} onChange={e => change(key, e.target.value)} />}</label>;
  const qrRow = selected;
  if (modal === 'qr') { const code = qrRow?.code || `LGRP-${qrRow?.id || '0000'}`; const payload = JSON.stringify({ sistema: 'LGRP-UFLA', codigo: code, nome: qrRow?.name || qrRow?.description || qrRow?.type || 'Identificação', id: qrRow?.id }); return <div className="qr-content"><div className="qr-display"><img src={`https://api.qrserver.com/v1/create-qr-code/?size=220x220&margin=12&data=${encodeURIComponent(payload)}`} alt={`QR Code para ${code}`} /><span><QrCode size={15} /> IDENTIFICAÇÃO LGRP</span></div><div className="qr-details"><span className="eyebrow">CÓDIGO ÚNICO</span><h3>{code}</h3><p>{qrRow?.name || qrRow?.description || qrRow?.type || 'Registro vinculado'}</p><div><span>Status</span><Status status={qrRow?.status || 'Identificado'} /></div><div><span>Origem / laboratório</span><b>{qrRow?.lab_name || qrRow?.assigned_lab || 'LGRP · UFLA'}</b></div><div><span>Identificador no sistema</span><b className="mono">#{qrRow?.id || '—'}</b></div><small>O QR contém apenas identificadores operacionais. Dados técnicos completos exigem autenticação.</small></div></div>; }
  if (modal === 'request') return <div className="form-grid">{input('Laboratório gerador *', 'lab_name', 'text', undefined, 'Ex.: Laboratório de Química Analítica')}{input('Solicitante responsável', 'requester', 'text', undefined, 'Nome do responsável')}{input('Descrição do resíduo *', 'description', 'text', undefined, 'Ex.: Solução aquosa de metais')}{input('Classe de risco *', 'hazard_class', 'text', ['Inflamável', 'Corrosivo', 'Reativo', 'Tóxico', 'Oxidante', 'Múltiplos riscos'])}{input('Quantidade estimada *', 'quantity', 'number', undefined, '0,00')}{input('Unidade', 'unit', 'text', ['kg', 'L', 'mL', 'g'])}{input('Estado físico', 'physical_state', 'text', ['Líquido', 'Sólido', 'Pastoso', 'Gasoso'])}<label className="span-2">Observações de segurança<textarea value={form.notes || ''} onChange={e => change('notes', e.target.value)} placeholder="Incompatibilidades, acondicionamento e riscos conhecidos" /></label></div>;
  if (modal === 'waste') return <div className="form-grid">{input('Nome do resíduo *', 'name', 'text', undefined, 'Identificação química ou descrição')}{input('Laboratório gerador *', 'lab_name', 'text', undefined, 'Unidade geradora')}{input('Composição química', 'composition', 'text', undefined, 'Constituintes conhecidos')}{input('Classe de risco *', 'hazard_class', 'text', ['Inflamável', 'Corrosivo', 'Reativo', 'Tóxico', 'Oxidante', 'Múltiplos riscos'])}{input('Estado físico', 'physical_state', 'text', ['Líquido', 'Sólido', 'Pastoso', 'Gasoso'])}{input('Quantidade *', 'quantity', 'number', undefined, '0,00')}{input('Unidade', 'unit', 'text', ['kg', 'L', 'mL', 'g'])}{input('Etapa atual', 'status', 'text', ['Gerado', 'Aguardando coleta', 'Em armazenamento', 'Em tratamento', 'Tratado', 'Destinado'])}{input('Recipiente', 'container_code', 'text', undefined, 'Código do recipiente')}{input('Local de armazenamento', 'storage_location', 'text', undefined, 'Ex.: Abrigo A · estante 2')}<label className="span-2">Observações<textarea value={form.notes || ''} onChange={e => change('notes', e.target.value)} placeholder="Compatibilidade e instruções de manuseio" /></label></div>;
  if (modal === 'container') return <div className="form-grid">{input('Tipo de recipiente *', 'type', 'text', ['Bombona PEAD', 'Frasco âmbar', 'Tambor metálico', 'Caixa para sólidos', 'Outro'])}{input('Material', 'material', 'text', ['PEAD', 'Vidro borossilicato', 'Aço carbono', 'Polipropileno'])}{input('Capacidade', 'capacity', 'number', undefined, '0,00')}{input('Unidade', 'unit', 'text', ['L', 'mL', 'kg'])}{input('Status', 'status', 'text', ['Disponível', 'Em uso', 'Inspeção', 'Inativo'])}{input('Laboratório atribuído', 'assigned_lab', 'text', undefined, 'Unidade responsável')}{input('Localização', 'location', 'text', undefined, 'Prateleira / abrigo')}{input('Validade / inspeção', 'expiry_date', 'date')}</div>;
  if (modal === 'reagent') return <div className="form-grid">{input('Nome do reagente *', 'name', 'text', undefined, 'Nome químico / comercial')}{input('Número CAS', 'cas_number', 'text', undefined, 'Ex.: 64-17-5')}{input('Laboratório', 'lab_name', 'text', undefined, 'Unidade responsável')}{input('Quantidade', 'quantity', 'number', undefined, '0,00')}{input('Unidade', 'unit', 'text', ['g', 'kg', 'mL', 'L', 'un'])}{input('Data de validade', 'expiry_date', 'date')}{input('Status', 'status', 'text', ['Em uso', 'Estoque', 'Vencido', 'Em descarte'])}{input('Localização', 'location', 'text', undefined, 'Armário / sala')}</div>;
  if (modal === 'schedule') return <div className="form-grid">{input('Data e horário da coleta', 'scheduled_at', 'datetime-local')}{input('Recipiente a entregar', 'container_code', 'text', undefined, 'Código do recipiente LGRP')}{input('Observações', 'notes', 'text', undefined, 'Orientações para o atendimento')}</div>;
  if (modal === 'operation') return <div className="form-grid">{input('Tipo de operação *', 'action', 'text', ['Coleta', 'Pesagem', 'Tratamento', 'Recuperação', 'Redução', 'Destinação'])}<label>Resíduo vinculado *<select value={form.waste_id || ''} onChange={e => change('waste_id', e.target.value)}><option value="">Selecione o resíduo…</option>{wastes.map((w: Row) => <option key={w.id} value={w.id}>{w.code} · {w.name} — {w.lab_name}</option>)}</select></label>{input('Responsável técnico', 'operator', 'text', undefined, 'Nome de quem executa')}{input('Massa bruta (kg)', 'gross_weight', 'number', undefined, '0,00')}{input('Tara (kg)', 'tare_weight', 'number', undefined, '0,00')}{input('Massa líquida (kg) * para coleta', 'net_weight', 'number', undefined, '0,00')}{input('Método / tecnologia', 'method', 'text', ['Neutralização', 'Destilação', 'Precipitação', 'Recuperação de solvente', 'Coprocessamento', 'Incineração', 'Outro'])}{input('Resultado / eficiência', 'outcome', 'text', undefined, 'Resultado observado')}{input('Destinação / receptor', 'destination', 'text', undefined, 'Unidade ou empresa licenciada')}{input('Nº manifesto / MTR', 'manifest', 'text', undefined, 'Identificador do documento')}{input('Recipiente / lacre', 'container_code', 'text', undefined, 'Código e lacre')}<label className="span-2">Notas e evidências<textarea value={form.notes || ''} onChange={e => change('notes', e.target.value)} placeholder="Condições, observações de segurança e referência documental" /></label></div>;
  if (modal === 'role') return <div className="form-grid">{input('Usuário', 'email', 'text')}{input('Perfil de acesso', 'role', 'text', roles)}<div className="span-2 permission-note"><ShieldCheck size={17} /><span>Alterações de perfil são operações críticas e ficam registradas na auditoria institucional.</span></div></div>;
  return null;
}
